// Some portions generated by Claude
// @ts-check
const { test, expect } = require('@playwright/test');
const {
    createSeededRepository,
    deleteRepository,
    evidencePath,
    evidenceScreenshots,
    repositoryPageUrl,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute
} = require('./workbench-test-helpers.js');

// The Graph page's React island reuses the Workbench design system: its background, text and font come from the
// --workbench-* tokens, it follows the light/dark switch, and it fills the window: no footer, no page scroll.
const REPOSITORY_ID = uniqueRepositoryId('graph-visual');
const EVIDENCE_DIR = process.env.E2E_GRAPH_EXPLORER_EVIDENCE_DIR || '';

test.beforeAll(async ({ request }) => {
    await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

async function openGraphPage(page, width, height) {
    await page.setViewportSize({ width, height });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    await page.locator('.graph-explorer').getByRole('button', { name: 'Load 100 statements' }).click();
    await page.locator('.graph-explorer .graph-node').first().waitFor({ state: 'attached', timeout: 30000 });
}

async function islandColours(page) {
    return page.evaluate(() => {
        const island = document.querySelector('.graph-explorer');
        const root = getComputedStyle(document.documentElement);
        const style = getComputedStyle(island);
        const probe = document.createElement('div');
        probe.style.background = root.getPropertyValue('--workbench-canvas').trim();
        probe.style.color = root.getPropertyValue('--workbench-ink').trim();
        document.body.appendChild(probe);
        const expected = { background: getComputedStyle(probe).backgroundColor, ink: getComputedStyle(probe).color,
            font: getComputedStyle(document.body).fontFamily };
        probe.remove();
        return {
            background: style.backgroundColor,
            ink: style.color,
            font: style.fontFamily,
            workbenchFont: root.getPropertyValue('--workbench-font').trim(),
            expected,
            scrollWidth: document.documentElement.scrollWidth,
            innerWidth: window.innerWidth,
            scrollHeight: document.documentElement.scrollHeight,
            innerHeight: window.innerHeight,
            footer: getComputedStyle(document.getElementById('footer')).display,
            topbar: document.querySelectorAll('.graph-explorer .topbar').length,
            fullBleed: document.getElementById('workbench-page-surface').classList.contains('workbench-page-surface--full-bleed')
        };
    });
}

// The toolbar shows its button labels while everything fits on one row with them, then only their icons, and only then
// its narrow layout (the views on a row of their own, the actions spread below): it never wraps on its own.
test('the toolbar turns to icons instead of breaking into two rows', async ({ page }) => {
    const errors = [];
    page.on('pageerror', (error) => errors.push(error.message));
    page.on('console', (message) => message.type() === 'error' && errors.push(message.text()));
    await openGraphPage(page, 1700, 900);
    const toolbar = page.locator('.graph-explorer .graph-toolbar');
    const state = () => toolbar.evaluate((bar) => {
        const items = [...bar.children];
        const tops = items.map((item) => Math.round(item.getBoundingClientRect().top));
        const views = bar.querySelector('.view-strip');
        const viewsTop = Math.round(views.getBoundingClientRect().top);
        return {
            fit: bar.dataset.fit,
            rows: new Set(tops).size,
            labels: getComputedStyle(bar.querySelector('.toolbar-label')).display !== 'none',
            viewsAlone: items.every((item) => item === views || Math.round(item.getBoundingClientRect().top) > viewsTop),
        };
    });
    const tidy = (entry) => entry.rows === 1 || (entry.fit === 'narrow' && entry.rows === 2 && entry.viewsAlone);
    const seen = [];
    for (const width of [1700, 1500, 1460, 1440, 1420, 1400, 1300, 1100, 1000, 950, 900, 1000, 1300, 1460, 1700]) {
        await page.setViewportSize({ width, height: 900 });
        await expect.poll(async () => tidy(await state()), { message: `a tidy toolbar at ${width}px` }).toBe(true);
        seen.push({ width, ...(await state()) });
    }
    expect(seen[0].labels, 'labels when there is room').toBe(true);
    expect(seen.some((entry) => entry.fit === 'icons' && entry.rows === 1), 'icons on one row before anything else').toBe(true);
    expect(seen[seen.length - 1].labels, 'labels again once there is room').toBe(true);
    expect(errors.filter((message) => /ResizeObserver/.test(message))).toEqual([]);
});

for (const theme of ['light', 'dark']) {
    test(`the graph explorer takes its surface, ink and font from the Workbench (${theme})`, async ({ page }) => {
        await page.addInitScript((preference) => localStorage.setItem('rdf4j-workbench-theme', preference), theme);
        await openGraphPage(page, 1440, 900);
        await expect(page.locator('html')).toHaveAttribute('data-theme', theme);

        const colours = await islandColours(page);
        expect(colours.background).toBe(colours.expected.background);
        expect(colours.ink).toBe(colours.expected.ink);
        expect(colours.font).toBe(colours.expected.font);
        expect(colours.topbar).toBe(0);
        expect(colours.fullBleed).toBe(true);
        expect(colours.scrollWidth).toBeLessThanOrEqual(colours.innerWidth);
        expect(colours.scrollHeight).toBeLessThanOrEqual(colours.innerHeight);
        expect(colours.footer).toBe('none');
        if (evidenceScreenshots()) {
            await page.screenshot({ path: evidencePath(EVIDENCE_DIR, `graph-explorer-${theme}-1440.png`), fullPage: false });
        }
    });
}

for (const [width, height] of [[1024, 768], [390, 844]]) {
    test(`the graph explorer fills the window at ${width}px without scrolling it either way`, async ({ page }) => {
        await openGraphPage(page, width, height);
        const colours = await islandColours(page);
        expect(colours.scrollWidth).toBeLessThanOrEqual(colours.innerWidth);
        expect(colours.scrollHeight).toBeLessThanOrEqual(colours.innerHeight);
        expect(colours.footer).toBe('none');
        if (evidenceScreenshots()) {
            await page.screenshot({ path: evidencePath(EVIDENCE_DIR, `graph-explorer-light-${width}.png`), fullPage: false });
        }
    });
}
